'use client';
import React, { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { usePathname } from 'next/navigation';
import A from './A';
import { MOBILE_NAV } from '../lib/nav';

// Hamburger menu for small screens (the desktop mega menu is hidden at 760px and below).
// Not generated by scripts/convert_design.py: the converter only inserts <MobileMenu />
// into each page's header. Styles are the .lc-mob-* rules in app/globals.css.
// The panel is portalled to <body> because the sticky header's backdrop-filter
// would otherwise trap a position: fixed child inside the header.
export default function MobileMenu() {
  const [open, setOpen] = useState(false);
  const [section, setSection] = useState(null);
  const [mounted, setMounted] = useState(false);
  const pathname = usePathname();

  useEffect(() => { setMounted(true); }, []);
  useEffect(() => { setOpen(false); }, [pathname]);

  useEffect(() => {
    if (!open) return undefined;
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
    const mq = window.matchMedia('(min-width: 761px)');
    const onWide = (e) => { if (e.matches) setOpen(false); };
    document.addEventListener('keydown', onKey);
    mq.addEventListener('change', onWide);
    document.documentElement.classList.add('lc-mob-lock');
    return () => {
      document.removeEventListener('keydown', onKey);
      mq.removeEventListener('change', onWide);
      document.documentElement.classList.remove('lc-mob-lock');
    };
  }, [open]);

  const close = () => setOpen(false);

  const panel = (
    <div id="lc-mob-panel" className="lc-mob-panel" role="dialog" aria-modal="true" aria-label="Menu" hidden={!open}>
      <div className="lc-mob-top">
        <A href="/" onClick={close} aria-label="LeMan Cave home" className="lc-mob-logo">
          <img src="/images/d8a1bc65662ee5a26ca2d3cbc9ca559e.svg" alt="LeMan Cave" />
        </A>
        <button type="button" className="lc-mob-btn" aria-label="Close menu" onClick={close}>
          <svg aria-hidden="true" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><path d="M6 6l12 12M18 6L6 18" /></svg>
        </button>
      </div>
      {/* Site search (CRM site-search widget, loaded in app/layout.tsx) */}
      <button type="button" className="lc-mob-search" onClick={() => { close(); window.SiteSearch?.open(''); }}>
        <svg aria-hidden="true" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><circle cx="11" cy="11" r="7" /><path d="M20 20l-3.5-3.5" /></svg>
        Search the site
      </button>
      <nav className="lc-mob-list" aria-label="Mobile">
        {MOBILE_NAV.map((item) => {
          if (!item.groups) {
            return <A key={item.label} href={item.href} className="lc-mob-item" onClick={close}>{item.label}</A>;
          }
          const isOpen = section === item.label;
          const id = 'lc-mob-' + item.label.toLowerCase().replace(/[^a-z]+/g, '-');
          return (
            <div key={item.label} className="lc-mob-sec">
              <button type="button" className="lc-mob-item" aria-expanded={isOpen} aria-controls={id}
                onClick={() => setSection(isOpen ? null : item.label)}>
                {item.label}
                <svg aria-hidden="true" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" style={{ transform: isOpen ? 'rotate(180deg)' : 'none', transition: 'transform .2s' }}><path d="M6 9l6 6 6-6" /></svg>
              </button>
              <div id={id} className="lc-mob-sub" hidden={!isOpen}>
                {item.groups.map((g) => (
                  <div key={g.title} className="lc-mob-group">
                    <span className="lc-mob-label">{g.title}</span>
                    {g.links.map(([href, text]) => (
                      <A key={href + text} href={href} onClick={close}>{text}</A>
                    ))}
                  </div>
                ))}
                <div className="lc-mob-more">
                  {(item.more || [[item.href, 'All ' + item.label.toLowerCase()]]).map(([href, text]) => (
                    <A key={href + text} href={href} onClick={close}>{text} {'→'}</A>
                  ))}
                </div>
              </div>
            </div>
          );
        })}
      </nav>
      <div className="lc-mob-foot">
        <A href="/book" className="lc-mob-book" onClick={close}>Book now</A>
        <a href="mailto:bookings@lemancave.co.uk">bookings@lemancave.co.uk</a>
        <span>Mon{'–'}Fri 06:30{'–'}21:30 {'·'} Sat 10:00{'–'}21:00</span>
      </div>
    </div>
  );

  return (
    <>
      <button type="button" className="lc-mob-btn lc-mob-open" aria-label="Open menu"
        aria-expanded={open} aria-controls="lc-mob-panel" onClick={() => setOpen(true)}>
        <svg aria-hidden="true" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><path d="M4 7h16M4 12h16M4 17h16" /></svg>
      </button>
      {mounted && createPortal(panel, document.body)}
    </>
  );
}
